
import { useEffect, useId, useState } from "react";
import AudioPlayer from "../AudioPlayer";

/**
 * JagadhatriLoader v3 — photo reveal. The face image stays untouched; the motion
 * lives in the elements around it: a drawing halo, blooming lotus mandala, drifting
 * tick ring, orbiting gold sparks, and a shockwave when the iris reveal lands.
 *
 * Self-contained (face image embedded as a data URI), transparent background.
 * Usage: <JagadhatriLoader size={280} />            // uses embedded face
 *        <JagadhatriLoader size={280} src="/face.jpg" />  // or your own image
 */

const CSS = `
.jg{
  --ease-reveal:cubic-bezier(.16,1,.3,1);   /* expo-out: fast launch, long soft landing */
  --ease-draw:cubic-bezier(.65,0,.35,1);    /* steep in-out: pen-like stroke drawing */
  --ease-pop:cubic-bezier(.34,1.56,.64,1);  /* back-out: ~10% overshoot, then settles */
  --ease-settle:cubic-bezier(.22,.61,.36,1);/* gentle decel for breathing / drift */
  --dur:7.5s;
  position:relative;display:inline-block;width:var(--jg-size,280px);aspect-ratio:1;
  background:transparent;animation:jg-cycle var(--dur) linear infinite;
}
.jg-layer{position:absolute;inset:0;width:100%;height:100%;overflow:visible}
.jg-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}

.jg-glow{transform-box:view-box;transform-origin:120px 120px;animation:jg-glow var(--dur) infinite}
.jg-halo{stroke-dasharray:1;transform:rotate(-90deg);transform-box:view-box;transform-origin:120px 120px;animation:jg-halo var(--dur) infinite}
.jg-ring{stroke-dasharray:1;transform:rotate(-90deg);transform-box:view-box;transform-origin:120px 120px;animation:jg-ring var(--dur) infinite}
.jg-ticks{transform-box:view-box;transform-origin:120px 120px;animation:jg-ticks var(--dur) infinite}
.jg-petals-a{transform-box:view-box;transform-origin:120px 120px;animation:jg-bloom-a var(--dur) infinite}
.jg-petals-b{transform-box:view-box;transform-origin:120px 120px;animation:jg-bloom-b var(--dur) infinite}
.jg-orbit{transform-box:view-box;transform-origin:120px 120px;animation:jg-orbit var(--dur) infinite}
.jg-pulse{transform-box:view-box;transform-origin:120px 120px;opacity:0;animation:jg-pulse var(--dur) infinite}

.jg-photo{
  position:absolute;left:50%;top:50%;width:64.17%;height:64.17%;transform:translate(-50%,-50%);border-radius:50%;overflow:hidden;
  animation:jg-iris var(--dur) infinite;
}
.jg-photo img{
  display:block;width:100%;height:100%;object-fit:cover;transform-origin:46% 38%;
  animation:jg-photo-img var(--dur) infinite;
}

@keyframes jg-cycle{
  0%{opacity:0;transform:scale(.94)}
  3%{opacity:1}
  30%{transform:scale(1);animation-timing-function:var(--ease-reveal)}
  89%{opacity:1;transform:scale(1);animation-timing-function:var(--ease-draw)}
  97%,100%{opacity:0;transform:scale(1.03)}
}
@keyframes jg-glow{
  0%,8%{opacity:0;transform:scale(.6);animation-timing-function:var(--ease-reveal)}
  40%{opacity:1;transform:scale(1);animation-timing-function:var(--ease-settle)}
  65%{opacity:.7;transform:scale(1.06);animation-timing-function:var(--ease-settle)}
  88%,100%{opacity:1;transform:scale(1)}
}
@keyframes jg-halo{
  0%,2%{stroke-dashoffset:1;animation-timing-function:var(--ease-draw)}
  26%,100%{stroke-dashoffset:0}
}
@keyframes jg-ring{
  0%,10%{stroke-dashoffset:1;opacity:0}
  11%{stroke-dashoffset:1;opacity:1;animation-timing-function:var(--ease-draw)}
  32%,100%{stroke-dashoffset:0;opacity:1}
}
@keyframes jg-ticks{
  0%,8%{opacity:0;transform:rotate(-40deg) scale(.86);animation-timing-function:var(--ease-reveal)}
  38%{opacity:1;transform:rotate(0) scale(1)}
  100%{opacity:1;transform:rotate(16deg) scale(1)}
}
@keyframes jg-bloom-a{
  0%,10%{opacity:0;transform:rotate(-50deg) scale(.55);animation-timing-function:var(--ease-pop)}
  40%{opacity:1;transform:rotate(0) scale(1);animation-timing-function:var(--ease-settle)}
  100%{opacity:1;transform:rotate(-14deg) scale(1)}
}
@keyframes jg-bloom-b{
  0%,14%{opacity:0;transform:rotate(60deg) scale(.5);animation-timing-function:var(--ease-pop)}
  44%{opacity:1;transform:rotate(0) scale(1);animation-timing-function:var(--ease-settle)}
  100%{opacity:1;transform:rotate(20deg) scale(1)}
}
@keyframes jg-orbit{
  0%,30%{opacity:0;transform:rotate(0)}
  34%{opacity:1;transform:rotate(0);animation-timing-function:var(--ease-draw)}
  100%{opacity:1;transform:rotate(300deg)}
}
@keyframes jg-pulse{
  0%,40%{opacity:0;transform:scale(1);animation-timing-function:var(--ease-reveal)}
  43%{opacity:.9}
  66%,100%{opacity:0;transform:scale(1.45)}
}
@keyframes jg-iris{
  0%,24%{clip-path:circle(0% at 46% 38%);animation-timing-function:var(--ease-reveal)}
  56%,100%{clip-path:circle(100% at 46% 38%)}
}
@keyframes jg-photo-img{
  0%,24%{transform:scale(1.35);filter:brightness(.55) saturate(.8);animation-timing-function:var(--ease-reveal)}
  62%{transform:scale(1);filter:brightness(1) saturate(1);animation-timing-function:var(--ease-settle)}
  100%{transform:scale(1);filter:brightness(1) saturate(1)}
}
@media (prefers-reduced-motion:reduce){
  .jg,.jg *{animation:none !important}
}
`;

const GOLD = "#e9a935";
const GOLD_LT = "#ffd871";
const RED = "#c4122b";

/** Petal pointing up from the centre (120,120); base radius r0, tip radius r1. */
const petal = (r0: number, r1: number, w: number) => {
  const m = (r0 + r1) / 2;
  return `M120 ${120 - r0} C${120 + w} ${120 - (r0 + (m - r0) * 0.6)} ${120 + w} ${120 - (m + (r1 - m) * 0.4)} 120 ${120 - r1} C${120 - w} ${120 - (m + (r1 - m) * 0.4)} ${120 - w} ${120 - (r0 + (m - r0) * 0.6)} 120 ${120 - r0} Z`;
};

const N = 16;
const OUTER = petal(76, 100, 8.5);
const INNER = petal(76, 91, 5.5);

export interface JagadhatriLoaderProps {
  /** Width in px or any CSS length. Height equals width. */
  size?: number | string;
  /** Optional face image URL. Defaults to the embedded crop. */
  src?: string;
  className?: string;
}

export default function JagadhatriLoader({ size = 280, src, className }: JagadhatriLoaderProps) {
  const id = useId().replace(/:/g, "");
  const glow = `jg-glow-${id}`;
  const w = typeof size === "number" ? `${size}px` : size;

  const [mounted, setMounted] = useState(false);
  useEffect(() => {

    if (!mounted) {
      setMounted(true);
    }

    document.body.style.overflow = "hidden";

    return () => {
      setMounted(false);

      document.body.style.overflow = "";
    };
  }, []);
  return (
    <div
      className={`jg ${className ?? ""}`}
      style={{ ["--jg-size" as string]: w }}
      role="status"
      aria-live="polite"
    >
      <style>{CSS}</style>
      <span className="jg-sr">Loading</span>

      {
        mounted && (
          <AudioPlayer />

        )
      }

      {/* Back layer: aura, mandala, halo, ticks, orbiting sparks */}
      <svg className="jg-layer" viewBox="0 0 240 240" aria-hidden="true">
        <defs>
          <radialGradient id={glow}>
            <stop offset="0.55" stopColor="#ff9a2e" stopOpacity="0" />
            <stop offset="0.78" stopColor="#ff9a2e" stopOpacity=".34" />
            <stop offset="1" stopColor="#ff9a2e" stopOpacity="0" />
          </radialGradient>
        </defs>

        <circle className="jg-glow" cx="120" cy="120" r="120" fill={`url(#${glow})`} />

        <g className="jg-petals-a">
          {Array.from({ length: N }, (_, i) => (
            <path key={i} d={OUTER} transform={`rotate(${(360 / N) * i} 120 120)`}
              fill={RED} fillOpacity=".92" stroke="#7a0c1c" strokeWidth=".7" />
          ))}
        </g>
        <g className="jg-petals-b">
          {Array.from({ length: N }, (_, i) => (
            <path key={i} d={INNER} transform={`rotate(${(360 / N) * i + 360 / N / 2} 120 120)`}
              fill={GOLD_LT} stroke="#b97a1c" strokeWidth=".7" />
          ))}
        </g>

        <circle className="jg-halo" cx="120" cy="120" r="104" pathLength={1}
          fill="none" stroke={GOLD} strokeWidth="2" strokeLinecap="round" />
        <circle className="jg-ticks" cx="120" cy="120" r="110" fill="none"
          stroke={GOLD_LT} strokeWidth="3.6" strokeDasharray="1.4 5.36" opacity=".9" />

        <g className="jg-orbit">
          <circle cx="120" cy="120" r="104" fill="none" />
          {[0, 120, 240].map((a) => (
            <circle key={a} cx="120" cy="16" r="3.4" fill={GOLD_LT} stroke={RED} strokeWidth="1"
              transform={`rotate(${a} 120 120)`} />
          ))}
        </g>
      </svg>

      {/* Face photo, revealed by an expanding iris with a settling zoom */}
      <div className="jg-photo" aria-hidden="true">
        <img src={src ?? FACE_SRC} alt="" draggable={false} />
      </div>

      {/* Front layer: photo rim + shockwave */}
      <svg className="jg-layer" viewBox="0 0 240 240" aria-hidden="true">
        <circle className="jg-pulse" cx="120" cy="120" r="77" fill="none" stroke={GOLD_LT} strokeWidth="2" />
        <circle className="jg-ring" cx="120" cy="120" r="77.5" pathLength={1}
          fill="none" stroke={GOLD} strokeWidth="2.6" strokeLinecap="round" />
      </svg>
    </div>
  );
}

const FACE_SRC =
  "data:image/jpeg;base64,";